int build_qfq(char *buf)
{
	char *qopt;
	short *tlen;
	char *qdisc = "qfq";

	short *optlen;
	short *opttype;

	tlen = buf;

	memset(buf, 0, sizeof(buf));
	memcpy(buf, linkcmd, sizeof(linkcmd));
	strcpy(buf+sizeof(linkcmd), qdisc);
	*tlen = sizeof(linkcmd) + strlen(qdisc) + 1;
	buf[36] = strlen(qdisc)+5;

	qopt = buf + *tlen;
	/* nla_len, nla_type */
	/* 24, 0x00, 0x02, 0x00, */
	optlen = qopt;
	opttype = optlen + 1;
	*opttype = 0x2;

	*optlen = 4;

	*tlen += *optlen;

	return *tlen;
}

